            center_x_w0: nx0,
            center_x_w1: nx1,
            center_x_w2: nx2,
            center_x_w3: nx3,
            center_y_w0: ny0,
            center_y_w1: ny1,
            center_y_w2: ny2,
            center_y_w3: ny3,
