/// pass reads the result from orbit metadata and does no depth probing.
pub fn sample_pixel(
    _ orbit: OrbitBuffer<ComplexQF32Bits, ORBIT_CAPACITY>,
    _ base: u32,
    _ center_x_w0: f32,
    _ center_x_w1: f32,
    _ center_x_w2: f32,
    _ center_x_w3: f32,
    _ center_y_w0: f32,
    _ center_y_w1: f32,
    _ center_y_w2: f32,
    _ center_y_w3: f32,
